theme.css:
/* theme: Digital Panic | The eMudhra collapse — trust infrastructure failing in an instant, markets scrambling for safety in defensives, the whole day read as error log lines. */
/* layout: hero=centered; political-news=numbered/grid-2; financial-news=split/grid-2; entertainment-news=plain/masonry; music-releases=tile/grid-2; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #0e0f13;
  --paper-alt: #15171d;
  --ink: #eef0f4;
  --ink-soft: #c4c8d2;
  --muted: #a0a6b3;
  --accent: #e0644d;
  --accent-ink: #0e0f13;
  --rule: #2b2f38;
  --font-display: var(--ff-space-grotesk), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-plex-mono), monospace;
  background-image: linear-gradient(rgba(224, 100, 77, 0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(224, 100, 77, 0.06) 1px, transparent 1px);
  background-size: 24px 24px;
  background-position: -1px -1px;
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-hero::after {
  content: "CA-INTERMEDIATE-KEY :: COMPROMISED // REVOCATION PENDING // TLS-HANDSHAKE-FAILED";
  position: absolute;
  right: 1.25rem;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--ff-plex-mono), monospace;
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  color: var(--accent);
  opacity: 0.7;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  max-height: 80%;
  overflow: hidden;
}

@media (max-width: 1023px) {
  .diary-page .diary-hero::after {
    display: none;
  }
}

.diary-page .diary-hero-inner {
  padding-block: 2.5rem 3.5rem;
}

.diary-page .diary-crumbs a {
  color: var(--muted);
}

.diary-page .diary-crumbs a::before {
  content: "← ";
}

.diary-page .diary-kicker {
  color: var(--accent);
  letter-spacing: 0.22em;
  font-size: 0.7rem;
}

.diary-page .diary-kicker::before,
.diary-page .diary-kicker::after {
  content: "▚▚ ";
}

.diary-page .diary-kicker::after {
  content: " ▞▞";
}

.diary-page .diary-title {
  max-width: 24ch;
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: clamp(2.4rem, 5.5vw, 4.5rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 0.98;
  text-transform: uppercase;
  color: var(--ink);
  position: relative;
  padding-bottom: 0.75rem;
  border-bottom: 3px solid var(--accent);
}

.diary-page[data-hero="centered"] .diary-title {
  margin-inline: auto;
  border-bottom-width: 4px;
}

.diary-page .diary-title::after {
  content: "TLS-HANDSHAKE-FAILED";
  display: block;
  font-family: var(--ff-plex-mono), monospace;
  font-size: 0.6rem;
  font-weight: 400;
  letter-spacing: 0.24em;
  color: var(--accent);
  margin-top: 0.75rem;
  text-transform: none;
}

.diary-page .diary-summary {
  color: var(--ink-soft);
  font-size: clamp(1.05rem, 1.8vw, 1.3rem);
  line-height: 1.6;
  max-width: 36rem;
}

.diary-page[data-hero="centered"] .diary-summary {
  margin-inline: auto;
}

.diary-page .diary-theme-note {
  color: var(--muted);
  font-size: 0.8rem;
  max-width: 36rem;
}

.diary-page[data-hero="centered"] .diary-theme-note {
  margin-inline: auto;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--ff-plex-mono), monospace;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  padding: 0.15rem 0.5rem;
  border-radius: 0;
}

.diary-page .diary-body {
  padding-bottom: 4rem;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--muted);
  font-size: 0.65rem;
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  color: var(--muted);
  font-size: 0.8rem;
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover {
  color: var(--ink);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 2.5rem;
}

.diary-page .diary-section-head {
  margin-bottom: 1.5rem;
  align-items: center;
}

.diary-page .diary-section-number {
  font-family: var(--ff-plex-mono), monospace;
  color: var(--accent);
  font-size: 0.7rem;
}

.diary-page .diary-section-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
}

.diary-page .diary-section-title::after {
  content: " /";
  color: var(--accent);
}

/* Political News — numbered cards */
.diary-page[data-section="political-news"] .diary-card--numbered .diary-card-inner {
  border-left: 2px solid var(--accent);
  padding-left: 1.5rem;
  padding-block: 1rem;
}

.diary-page[data-section="political-news"] .diary-card--numbered .diary-card-index {
  font-family: var(--ff-plex-mono), monospace;
  font-size: 2.25rem;
  font-weight: 600;
  color: var(--accent);
  line-height: 1;
}

.diary-page[data-section="political-news"] .diary-card-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page[data-section="political-news"] .diary-card-body {
  font-size: 1.02rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

/* Financial News — split cards */
.diary-page[data-section="financial-news"] .diary-card--split .diary-card-inner {
  padding-top: 1rem;
  border-top: 2px solid var(--accent);
}

.diary-page[data-section="financial-news"] .diary-card--split .diary-card-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 1.15rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
}

.diary-page[data-section="financial-news"] .diary-card--split .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page[data-section="financial-news"] .diary-card--split .diary-card-body strong {
  color: var(--accent);
  font-weight: 600;
}

/* Entertainment — plain masonry with drop-caps */
.diary-page[data-section="entertainment-news"] .diary-card--plain .diary-card-inner {
  padding: 0 0 1.5rem;
}

.diary-page[data-section="entertainment-news"] .diary-card--plain .diary-card-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 1.35rem;
  font-weight: 600;
  color: var(--ink);
  letter-spacing: -0.02em;
}

.diary-page[data-section="entertainment-news"] .diary-card--plain .diary-card-body {
  font-size: 1.02rem;
  color: var(--ink-soft);
  line-height: 1.8;
}

.diary-page[data-section="entertainment-news"] .diary-card--plain .diary-card-body::first-letter {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 2.4em;
  font-weight: 700;
  float: left;
  line-height: 0.8;
  padding-right: 0.08em;
  color: var(--accent);
}

/* Music Releases — tiles */
.diary-page[data-section="music-releases"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 1.25rem;
  position: relative;
}

.diary-page[data-section="music-releases"] .diary-card--tile .diary-card-inner::before {
  content: "▶";
  position: absolute;
  top: 0.5rem;
  right: 0.75rem;
  font-size: 0.7rem;
  color: var(--accent);
}

.diary-page[data-section="music-releases"] .diary-card--tile .diary-card-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--ink);
  text-transform: none;
  letter-spacing: -0.01em;
}

.diary-page[data-section="music-releases"] .diary-card--tile .diary-card-body {
  font-size: 0.95rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.diary-page[data-section="music-releases"] .diary-card--tile .diary-card-body strong {
  color: var(--accent);
}

/* Stock Analysis — stat cards */
.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  padding-top: 0.75rem;
  border-top: 2px solid var(--accent);
}

.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-figure {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: clamp(1.8rem, 10cqi, 2.75rem);
  font-weight: 700;
  color: var(--accent);
  letter-spacing: -0.03em;
  line-height: 1;
}

.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink);
}

.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-body {
  font-size: 0.92rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-body strong {
  color: var(--accent);
}

.diary-page[data-section="stock-analysis"] .diary-stories--grid-3 {
  gap: 1rem;
}

.diary-page[data-section="stock-analysis"] .diary-stories--grid-3 .diary-card--stat .diary-card-inner {
  gap: 0.6rem;
}

/* Outlook — timeline */
.diary-page[data-section="outlook"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page[data-section="outlook"] .diary-card--timeline .diary-card-inner::before {
  left: 0.35rem;
  background: var(--rule);
}

.diary-page[data-section="outlook"] .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page[data-section="outlook"] .diary-card--timeline .diary-card-title {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.diary-page[data-section="outlook"] .diary-card--timeline .diary-card-body {
  font-size: 1.02rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

/* Card thread labels */
.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-size: 0.7rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Prose styling */
.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: currentColor;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.5rem;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

/* Markets sparklines */
.diary-page .diary-markets-label {
  color: var(--muted);
  font-size: 0.65rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up {
  color: #4cc38a;
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

/* Footer */
.diary-page .diary-footer {
  border-top-color: var(--rule);
  font-family: var(--ff-plex-mono), monospace;
  font-size: 0.8rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}
